"""Music-theory glue over midi-composer-mcp: note/chord spelling, scales, analysis.

Chord symbols, scale names and spelling all come from the midi-composer-mcp
library so every chord in a score is parsed by the same rules the MCP tools use.
"""
from __future__ import annotations

from dataclasses import dataclass
from functools import lru_cache

from midi_composer_mcp.chords import chord_notes, parse_chord_symbol
from midi_composer_mcp.harmony import analyze_progression
from midi_composer_mcp.notes import parse_note
from midi_composer_mcp.scales import resolve_scale_type, scale_notes

NAMES_SHARP = ("C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B")
NAMES_FLAT = ("C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B")


@lru_cache(None)
def midi(name: str) -> int:
    n = parse_note(name)
    if n.octave is None:
        raise ValueError(f"note {name!r} needs an octave")
    return n.midi


def pc_name(pc: int, flats: bool = False) -> str:
    return (NAMES_FLAT if flats else NAMES_SHARP)[pc % 12]


def note_name(m: int, flats: bool = False) -> str:
    return f"{pc_name(m, flats)}{m // 12 - 1}"


@dataclass(frozen=True)
class Chord:
    symbol: str
    root: int                 # pitch class
    intervals: tuple          # semitones above the root (extensions keep > 12)
    labels: tuple             # degree labels, e.g. ("1", "b3", "5", "b7")
    bass: int                 # pitch class in the bass (slash note or root)
    spelled: tuple            # spelled note names, e.g. ("F#", "A", "C#")

    @property
    def pcs(self) -> frozenset:
        return frozenset((self.root + i) % 12 for i in self.intervals)

    def pc_of(self, label: str):
        for lab, iv in zip(self.labels, self.intervals):
            if lab == label:
                return (self.root + iv) % 12
        return None

    @property
    def third(self):
        return self.pc_of("3") if self.pc_of("3") is not None else self.pc_of("b3")

    @property
    def seventh(self):
        for lab in ("b7", "7", "bb7"):
            if self.pc_of(lab) is not None:
                return self.pc_of(lab)
        return None

    @property
    def is_dominant(self) -> bool:
        return self.pc_of("3") is not None and self.pc_of("b7") is not None


@lru_cache(None)
def chord(symbol: str) -> Chord:
    root, ctype, bass = parse_chord_symbol(symbol)
    tones = chord_notes(ctype, root)
    labels = tuple(lab for lab, _ in ctype.degrees)
    return Chord(
        symbol=symbol,
        root=root.pitch_class,
        intervals=tuple(ctype.intervals),
        labels=labels,
        bass=(bass.pitch_class if bass is not None else root.pitch_class),
        spelled=tuple(t.pitch_class_name for t in tones),
    )


@lru_cache(None)
def scale_pcs(tonic: str, mode: str) -> frozenset:
    st = resolve_scale_type(mode)
    return frozenset(n.pitch_class for n in scale_notes(st, parse_note(tonic)))


@lru_cache(None)
def scale_names(tonic: str, mode: str) -> tuple:
    st = resolve_scale_type(mode)
    return tuple(n.pitch_class_name for n in scale_notes(st, parse_note(tonic))[:-1])


def roman(symbols, tonic: str, mode: str) -> list[str]:
    """Roman numerals for chord symbols (slash basses kept as /bass)."""
    res = analyze_progression(list(symbols), tonic, mode)
    out = []
    for sym, entry in zip(symbols, res["chords"]):
        r = entry["roman"]
        if "/" in sym:
            r += "/" + sym.split("/")[-1]
        out.append(r)
    return out

