        if m:
            v = DUR[m.group(1)]
            if m.group(2) == ".":
                v *= 1.5
            elif m.group(2) == "..":
                v *= 1.75
            if m.group(3):
                v *= 2.0 / 3.0
        else:
            v = float(part)
        total += v
    return total


@dataclass
class Event:
    start: float
    dur: float
    pitch: str
    flags: str


def parse_line(text: str, bar_len: float, partial_last: bool = False) -> tuple[list[Event], float]:
    """Parse a bar-structured line into events (ties merged). Returns (events, length)."""
    bars = [b.strip() for b in text.strip().strip("|").split("|")]
    events: list[Event] = []
    pos = 0.0
    last_dur = 1.0
    for bi, bar in enumerate(bars):
        bar_start = pos
        for tok in bar.split():
            flags = ""
            while tok and tok[-1] in FLAG_CHARS:
                flags = tok[-1] + flags
                tok = tok[:-1]
            if ":" in tok:
                p, d = tok.split(":", 1)
                last_dur = parse_dur(d)
            else:
                p = tok
            events.append(Event(pos, last_dur, p, flags))
            pos += last_dur
        got = pos - bar_start
        if abs(got - bar_len) > 1e-6 and not (partial_last and bi == len(bars) - 1):
            raise ValueError(f"bar {bi + 1} lasts {got:g} beats, expected {bar_len:g}: '{bar}'")
    merged: list[Event] = []
    for ev in events:
        if (merged and "~" in merged[-1].flags and merged[-1].pitch == ev.pitch
                and abs(merged[-1].start + merged[-1].dur - ev.start) < 1e-6):
            prev = merged[-1]
            prev.dur += ev.dur
            prev.flags = prev.flags.replace("~", "") + ev.flags
            continue
        merged.append(ev)
    return merged, pos


def pitches_of(p: str) -> list[int]:
    if p.startswith("["):
        return [midi(x.strip()) for x in p[1:-1].split(",")]
    return [midi(p)]


@dataclass
class Note:
    start: float        # beats
    dur: float          # beats
    pitch: int
    vel: int
    flags: str = ""

    @property
    def end(self):
        return self.start + self.dur


class Track:
    def __init__(self, song, name, patch, program=0, role="lead", check=False,
                 channel=None, **mix):
        self.song = song
        self.name = name
        self.patch = patch
        self.program = program
        self.role = role
        self.check = check
        self.channel = channel
        self.notes: list[Note] = []
        self.mix = {"gain": 0.0, "pan": 0.0, "rev": 0.0, "dly": 0.0, "duck": 0.0,
                    "width": 1.0, "hpf": 0.0, "lpf": 0.0, "chorus": 0.0, "drive": 0.0}
        self.mix.update(mix)
        self.auto: dict[str, list] = {}
        self.last_voicing = None

    def add(self, start, dur, pitch, vel=96, flags=""):
        self.notes.append(Note(float(start), float(dur), int(pitch),
                               int(max(1, min(127, round(vel)))), flags))

    def automate(self, param, points):
        """points: [(beat, value), ...] — cutoff in Hz or gain in dB."""
        self.auto.setdefault(param, []).extend(points)


def parse_progression(text: str, bars: int, bar_len: float) -> list[tuple[float, float, Chord]]:
    """'Am | F C | G:3 E7:1' -> [(start, dur, Chord)], cycled to fill `bars`."""
    src = [b.strip() for b in text.strip().strip("|").split("|") if b.strip()]
    if not src:
        return []
    out = []
    prev = None
    for b in range(bars):
        toks = src[b % len(src)].split()
        weights = []
        syms = []
        for t in toks:
            if ":" in t:
                s, w = t.split(":")
                weights.append(float(w))
            else:
                s = t
                weights.append(None)
            if s == "%":
                s = prev
            syms.append(s)
            prev = s
        fixed = sum(w for w in weights if w is not None)
        free = [w for w in weights if w is None]
        each = (bar_len - fixed) / len(free) if free else 0.0
        pos = b * bar_len
        for s, w in zip(syms, weights):
            d = w if w is not None else each
            out.append((pos, d, chord(s)))
            pos += d
        if abs(pos - (b + 1) * bar_len) > 1e-6:
            raise ValueError(f"progression bar '{src[b % len(src)]}' does not fill {bar_len} beats")
    return out


def merge_chords(chords):
    """Join consecutive identical chords (for held pads)."""
    out = []
    for s, d, c in chords:
        if out and out[-1][2].symbol == c.symbol and abs(out[-1][0] + out[-1][1] - s) < 1e-6:
            out[-1] = (out[-1][0], out[-1][1] + d, c)
        else:
            out.append((s, d, c))
    return out


_IMPORTANCE = ["3", "b3", "4", "2", "7", "b7", "bb7", "b5", "#5", "9", "b9", "#9",
               "5", "1", "6", "#11", "11", "13", "b13"]


def voice_chord(ch: Chord, prev, lo: int, hi: int, n: int, top=None):
    """Pick a smooth voicing of `ch` with n notes inside [lo, hi]."""
    by_label = dict(zip(ch.labels, [(ch.root + i) % 12 for i in ch.intervals]))
    chosen = []
    for lab in _IMPORTANCE:
        pc = by_label.get(lab)
        if pc is not None and pc not in chosen:
            chosen.append(pc)
    chosen = chosen[:n]
    while len(chosen) < n:  # double root, then fifth
        chosen.append(ch.root if chosen.count(ch.root) <= chosen.count(by_label.get("5", ch.root)) else by_label.get("5", ch.root))
    cands = [[m for m in range(lo, hi + 1) if m % 12 == pc] for pc in chosen]
    center = (lo + hi) / 2
    best, best_cost = None, None
    for combo in itertools.product(*cands):
        s = sorted(combo)
        if len(set(s)) < len(s) or s[-1] - s[0] > 19:
            continue
        cost = 0.0
        if prev is not None and len(prev) == len(s):
            cost += sum(abs(a - b) for a, b in zip(prev, s))
        elif prev is not None:
            cost += sum(min(abs(a - b) for b in prev) for a in s)
        cost += 0.35 * abs(np.mean(s) - center)
        for a, b in zip(s, s[1:]):
            if b - a == 1:
                cost += 7.0
            elif b - a == 2 and a < 55:
                cost += 2.0
        if s[0] < 52 and s[1] - s[0] < 5:
            cost += 5.0
        if top is not None:
            cost += 0.8 * abs(s[-1] - top)
        if best_cost is None or cost < best_cost:
            best, best_cost = s, cost
    if best is None:
        raise ValueError(f"cannot voice {ch.symbol} in [{lo},{hi}] with {n} notes")
    return best


def metric_accent(pos: float, bar_len: float) -> float:
    p = pos % bar_len
    if abs(p) < 1e-6:
        return 8.0
    if bar_len == 4 and abs(p - 2.0) < 1e-6:
        return 4.0
    if abs(p - round(p)) < 1e-6:
        return 1.0
    if abs(p * 2 - round(p * 2)) < 1e-6:
        return -5.0
    return -9.0


DRUM_KEYS = {"kick": 36, "snare": 38, "rim": 37, "clap": 39, "hat": 42, "phat": 44,
             "ohat": 46, "crash": 49, "ride": 51, "tom1": 50, "tom2": 47, "tom3": 43,
             "shaker": 82, "tamb": 54, "taiko": 35, "boom": 41, "metal": 56}
DRUM_VEL = {"X": 122, "x": 102, "o": 80, "g": 56}


class Section:
    def __init__(self, song, name, start, bars, chords_text):
        self.song = song
        self.name = name
        self.start = start
        self.bars = bars
        self.bpb = song.meter
        self.length = bars * self.bpb
        self.chords = parse_progression(chords_text, bars, self.bpb) if chords_text else []

    # -- timing
    def at(self, bar=0, beat=0.0):
        return self.start + bar * self.bpb + beat

    def chord_at(self, rel):
        for s, d, c in self.chords:
            if s - 1e-9 <= rel < s + d - 1e-9:
                return c
        return self.chords[-1][2] if self.chords else None

    def _chords_in(self, bars):
        if bars is None:
            return self.chords
        b0, b1 = bars
        lo, hi = b0 * self.bpb, b1 * self.bpb
        out = []
        for s, d, c in self.chords:
            e = s + d
            if e <= lo + 1e-9 or s >= hi - 1e-9:
                continue
            out.append((max(s, lo), min(e, hi) - max(s, lo), c))
        return out

    # -- writing
    def mel(self, track, text, bar=0, beat=0.0, transpose=0, vel=94, partial=False,
            gate=1.0):
        events, _ = parse_line(text, self.bpb, partial)
        base = self.at(bar, beat)
        for ev in events:
            if ev.pitch == "r":
                continue
            v = vel + metric_accent(ev.start + beat, self.bpb) + (0.6 if ev.dur >= 1 else 0) * 4
            if "!" in ev.flags:
                v += 14
            if "?" in ev.flags:
                v -= 18
            v += self.song.rng.normal(0, 2.0)
            for p in pitches_of(ev.pitch):
                track.add(base + ev.start, ev.dur * gate, p + transpose, v, ev.flags)

    def pad(self, track, lo="A3", hi="E5", voices=4, vel=70, hold=True, rhythm=None,
            bars=None, top=None, gate=1.0):
        """Voice-led chords. rhythm: per-bar step string ('x' hit, '-' hold, '.' rest)."""
        lo_m, hi_m = midi(lo), midi(hi)
        chords = merge_chords(self._chords_in(bars)) if hold else self._chords_in(bars)
        for s, d, c in chords:
            v = voice_chord(c, track.last_voicing, lo_m, hi_m, voices,
                            None if top is None else midi(top))
            track.last_voicing = v
            if rhythm is None:
                for p in v:
                    track.add(self.at(0, s), d * gate, p, vel)
                continue
            steps = rhythm.replace(" ", "").replace("|", "")
            step = self.bpb / len(steps)
            k = 0
            t = s
            while t < s + d - 1e-9:
                idx = int(round((t % self.bpb) / step)) % len(steps)
                ch_ = steps[idx]
                if ch_ in "xXo":
                    ln = step
                    j = idx + 1
                    while j < len(steps) and steps[j] == "-" and t + ln < s + d - 1e-9:
                        ln += step
                        j += 1
                    acc = {"X": 12, "x": 0, "o": -12}[ch_]
                    for p in v:
                        track.add(self.at(0, t), min(ln, s + d - t) * gate, p, vel + acc)
                t += step
                k += 1

    def _degree(self, c: Chord, deg: str, base: int) -> int:
        """Resolve a bass/arp degree relative to chord c above bass pitch `base`."""
        if deg == "R":
            return base
        if deg == "O":
            return base + 12
        if deg == "O2":
            return base + 24
        root = base + ((c.root - base) % 12)
        if root - base > 0 and deg in ("1", "5", "3", "7", "9", "5-"):
            pass
        lab_map = {"1": ["1"], "3": ["3", "b3", "4", "2"], "5": ["5", "b5", "#5"],
                   "7": ["7", "b7", "bb7"], "9": ["9", "b9", "#9", "2"]}
        if deg == "5-":
            p = self._degree(c, "5", base)
            return p - 12
        for lab in lab_map[deg]:
            pc = c.pc_of(lab)
            if pc is not None:
                return base + ((pc - base) % 12)
        return base

    def bass(self, track, pattern="R:e R R R R R R R", lo="E1", vel=100, gate=0.82,
             bars=None, accent=True):
        """Bass line from a per-bar degree pattern (R, O, 1, 3, 5, 5-, 7, 9, r)."""
        lo_m = midi(lo)
        events, plen = parse_line(pattern, self.bpb * max(1, pattern.count("|") + 1), True)
        b0, b1 = bars if bars else (0, self.bars)
        t = b0 * self.bpb
        while t < b1 * self.bpb - 1e-9:
            for ev in events:
                at = t + ev.start
                if at >= b1 * self.bpb - 1e-9:
                    break
                if ev.pitch == "r":
                    continue
                c = self.chord_at(at)
                base = lo_m + ((c.bass - lo_m) % 12)
                p = self._degree(c, ev.pitch, base)
                v = vel + (metric_accent(at, self.bpb) * 0.8 if accent else 0)
                if "!" in ev.flags:
                    v += 12
                if "?" in ev.flags:
                    v -= 16
                d = min(ev.dur, b1 * self.bpb - at)
                track.add(self.at(0, at), d * gate, p, v, ev.flags)
            t += plen

    def arp(self, track, pattern="up", rate=0.25, lo="A3", octaves=2, vel=78, gate=0.7,
            bars=None, accent=6, restart=True):
        """Arpeggiate chord tones inside [lo, lo + octaves*12). pattern: 'up', 'down',
        'updown', 'converge' or a list of indices into the ascending tone list."""
        lo_m = midi(lo)
        b0, b1 = bars if bars else (0, self.bars)
        t = b0 * self.bpb
        k = 0
        last_c = None
        while t < b1 * self.bpb - 1e-9:
            c = self.chord_at(t)
            if restart and (last_c is None or c.symbol != last_c.symbol):
                k = 0
            last_c = c
            tones = sorted(m for m in range(lo_m, lo_m + 12 * octaves) if m % 12 in c.pcs)
            n = len(tones)
            if isinstance(pattern, str):
                if pattern == "up":
                    seq = list(range(n))
                elif pattern == "down":
                    seq = list(range(n - 1, -1, -1))
                elif pattern == "updown":
                    seq = list(range(n)) + list(range(n - 2, 0, -1))
                elif pattern == "converge":
                    seq = [i for pair in zip(range(n), range(n - 1, -1, -1)) for i in pair][:n]
                else:
                    raise ValueError(pattern)
            else:
                seq = pattern
            idx = seq[k % len(seq)] % n
            v = vel + (accent if abs((t % 1.0)) < 1e-6 else 0) + self.song.rng.normal(0, 2)
            track.add(self.at(0, t), rate * gate, tones[idx], v)
            t += rate
            k += 1

    def drums(self, track, pattern: dict, bars=None, step=0.25, vel=0, fills=None):
        """pattern: {'kick': 'x...x...', ...}, one char per step, repeating.
        fills: {bar_index: pattern_dict} replaces the whole kit for that bar."""
        b0, b1 = bars if bars else (0, self.bars)
        spb = int(round(self.bpb / step))
        for b in range(b0, b1):
            pat = fills.get(b if b >= 0 else b, None) if fills else None
            if fills and pat is None and (b - self.bars) in fills:
                pat = fills[b - self.bars]
            pat = pat or pattern
            for name, s in pat.items():
                s = s.replace(" ", "").replace("|", "")
                key = DRUM_KEYS[name]
                for k in range(spb):
                    ch_ = s[((b - b0) * spb + k) % len(s)] if pat is pattern else s[k % len(s)]
                    if ch_ in DRUM_VEL:
                        v = DRUM_VEL[ch_] + vel + self.song.rng.normal(0, 3)
                        track.add(self.at(b, k * step), step, key, v)

    def hit(self, track, name, bar=0, beat=0.0, vel=110, dur=0.25):
        track.add(self.at(bar, beat), dur, DRUM_KEYS[name] if isinstance(name, str) else name, vel)

    def fx(self, track, kind, bar=0, beat=0.0, beats=4.0, vel=100):
        """FX events: riser (ends at bar/beat + beats), impact, reverse (peaks at end)."""
        key = {"riser": 48, "impact": 50, "reverse": 52, "downlifter": 53, "swell": 55}[kind]
        track.add(self.at(bar, beat), beats, key, vel)


class Song:
    def __init__(self, title, slug, bpm, tonic, mode, meter=4, seed=1, genre="",
                 time_sig=None):
        self.title = title
        self.slug = slug
        self.bpm = float(bpm)
        self.meter = meter
        self.time_sig = time_sig or (meter, 4)
        self.genre = genre
        self.tracks: dict[str, Track] = {}
        self.sections: list[Section] = []
        self.keys = [(0.0, tonic, mode)]
        self.cursor = 0.0
        self.rng = np.random.default_rng(seed)
        self.seed = seed
        self.bus = {"rev_rt60": 2.4, "rev_pre": 0.025, "rev_bright": 9000.0, "rev_dark": 2200.0,
                    "rev_gain": 0.0, "dly_beats": 0.75, "dly_fb": 0.38, "dly_damp": 0.35,
                    "gated_rt60": 0.9, "gate_hold": 0.24}
        self.master = {"lufs": -11.5, "ceiling_db": -1.0, "glue": True, "tail": 5.0,
                       "tilt": 0.0}
        self.notes_text = ""

    @property
    def tonic(self):
        return self.keys[0][1]

    @property
    def mode(self):
        return self.keys[0][2]

    def track(self, name, patch, **kw) -> Track:
        t = Track(self, name, patch, **kw)
        self.tracks[name] = t
        return t

    def section(self, name, bars, chords="", tonic=None, mode=None) -> Section:
        if tonic or mode:
            t0, m0 = self.key_at(self.cursor)
            self.keys.append((self.cursor, tonic or t0, mode or m0))
        s = Section(self, name, self.cursor, bars, chords)
        self.sections.append(s)
        self.cursor += s.length
        return s

    def key_at(self, beat):
        cur = self.keys[0]
        for k in self.keys:
            if k[0] <= beat + 1e-9:
                cur = k
        return cur[1], cur[2]

    def chord_at(self, beat):
        for s in self.sections:
            if s.start - 1e-9 <= beat < s.start + s.length - 1e-9:
                return s.chord_at(beat - s.start) if s.chords else None
        return None

    def sec(self, beats):
        return beats * 60.0 / self.bpm

    @property
    def length_beats(self):
        return self.cursor

