"""Standard MIDI File export (format 1) with tempo, meter, key signatures,
section markers, GM programs, volume/pan and per-note velocities."""
from __future__ import annotations

import mido

from .instruments import DrumKit, FX

PPQ = 480
MINOR_MODES = {"natural minor", "harmonic minor", "melodic minor", "dorian", "phrygian",
               "locrian", "hungarian minor", "phrygian dominant", "aeolian"}
ENHARMONIC_MINOR = {"Db": "C#", "Gb": "F#", "A#": "Bb", "D#": "D#", "Ab": "G#"}
ENHARMONIC_MAJOR = {"A#": "Bb", "D#": "Eb", "G#": "Ab", "C#": "Db", "Gb": "Gb"}


def key_name(tonic: str, mode: str) -> str:
    if mode in MINOR_MODES:
        return ENHARMONIC_MINOR.get(tonic, tonic) + "m"
    return ENHARMONIC_MAJOR.get(tonic, tonic)


def _ticks(beats):
    return int(round(beats * PPQ))


def write(song, path):
    mid = mido.MidiFile(type=1, ticks_per_beat=PPQ)
    cond = mido.MidiTrack()
    mid.tracks.append(cond)
    ev = [(0, 0, mido.MetaMessage("track_name", name=song.title)),
          (0, 1, mido.MetaMessage("set_tempo", tempo=mido.bpm2tempo(song.bpm))),
          (0, 2, mido.MetaMessage("time_signature", numerator=song.time_sig[0],
                                  denominator=song.time_sig[1]))]
    for beat, tonic, mode in song.keys:
        ev.append((_ticks(beat), 3, mido.MetaMessage("key_signature", key=key_name(tonic, mode))))
    for s in song.sections:
        ev.append((_ticks(s.start), 4, mido.MetaMessage("marker", text=s.name)))
    ev.append((_ticks(song.length_beats), 9, mido.MetaMessage("end_of_track")))
    _emit(cond, ev)

    channel = 0
    for tr in song.tracks.values():
        if not tr.notes:
            continue
        if isinstance(tr.patch, DrumKit):
            ch = 9
        else:
            ch = tr.channel if tr.channel is not None else channel
            channel += 1
            if channel == 9:
                channel += 1
        t = mido.MidiTrack()
        mid.tracks.append(t)
        vol = int(max(20, min(127, 100 * 10 ** (tr.mix["gain"] / 40))))
        pan = int(max(0, min(127, 64 + tr.mix["pan"] * 63)))
        name = tr.name + (" (audio FX cues)" if isinstance(tr.patch, FX) else "")
        ev = [(0, 0, mido.MetaMessage("track_name", name=name)),
              (0, 1, mido.Message("program_change", program=tr.program, channel=ch)),
              (0, 2, mido.Message("control_change", control=7, value=vol, channel=ch)),
              (0, 3, mido.Message("control_change", control=10, value=pan, channel=ch))]
        # no overlapping notes of the same pitch on a channel
        last_end = {}
        for nt in sorted(tr.notes, key=lambda x: (x.start, x.pitch)):
            on = _ticks(nt.start)
            off = max(on + 1, _ticks(nt.end))
            prev = last_end.get(nt.pitch)
            if prev is not None and prev[1] > on:
                prev[0][0] = max(prev[2] + 1, on)
            item = [off, 5, mido.Message("note_off", note=nt.pitch, velocity=0, channel=ch)]
            ev.append(item)
            ev.append((on, 6, mido.Message("note_on", note=nt.pitch, velocity=nt.vel, channel=ch)))
            last_end[nt.pitch] = (item, off, on)
        end = max(e[0] for e in ev)
        ev.append((end, 9, mido.MetaMessage("end_of_track")))
        _emit(t, [tuple(e) for e in ev])
    mid.save(path)
    return path


def _emit(track, events):
    events = sorted(events, key=lambda e: (e[0], e[1]))
    now = 0
    for tick, _, msg in events:
        track.append(msg.copy(time=tick - now))
        now = tick

